DbcsWidthToggles dbcs_width_toggles(DbcsCodepage codepage) noexcept {
  switch (codepage) {
    case DbcsCodepage::kJis0208:
      return {kJis0208Toggles, sizeof(kJis0208Toggles) / sizeof(std::uint16_t)};
    case DbcsCodepage::kGb2312:
      return {kGb2312Toggles, sizeof(kGb2312Toggles) / sizeof(std::uint16_t)};
    case DbcsCodepage::kKsX1001:
      return {kKsx1001Toggles, sizeof(kKsx1001Toggles) / sizeof(std::uint16_t)};
    case DbcsCodepage::kBig5:
      return {kBig5Toggles, sizeof(kBig5Toggles) / sizeof(std::uint16_t)};
    default:
      return {nullptr, 0};
  }
}

